    function _getErc7739HashAndSignature(
        address account,
        address sender,
        bytes32 hash,
        bytes calldata signature
    )
        internal
        view
        virtual
        returns (bytes32, bytes calldata)
    {
        if (_erc1271CallerIsSafe(account, sender)) {
